Evaluate the JavaScript procedural FPS map generator implementation on a scale of 0-10 points:

**Map Generation Quality (4 points)**: Does it create realistic, playable FPS maps with proper room layouts, corridors, and tactical positions? Are maps varied and interesting rather than random noise?

**Connectivity & Features (3 points)**: Does it properly implement flood-fill to ensure all areas are reachable? Are spawn points and weapon pickups strategically placed?

**Performance & Interface (2 points)**: Does it generate maps efficiently at 60 FPS? Does the "Generate New Map" button work with a clear legend?

**Code Architecture (1 point)**: Is the code well-structured with proper procedural generation algorithms and error handling?

Solution A: ```javascript
function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    const cellSize = 10;
    const mapWidth = width / cellSize;
    const mapHeight = height / cellSize;

    let map = [];
    for (let y = 0; y < mapHeight; y++) {
        map[y] = [];
        for (let x = 0; x < mapWidth; x++) {
            map[y][x] = 0; // 0: floor, 1: wall
        }
    }

    function createRoom(x, y, w, h) {
        for (let i = x; i < x + w; i++) {
            for (let j = y; j < y + h; j++) {
                if (i > 0 && i < mapWidth - 1 && j > 0 && j < mapHeight - 1) {
                    map[j][i] = 0;
                }
            }
        }
    }

    function createCorridor(x1, y1, x2, y2) {
        while (x1 !== x2 || y1 !== y2) {
            if (x1 < x2) x1++;
            else if (x1 > x2) x1--;
            else if (y1 < y2) y1++;
            else if (y1 > y2) y1--;

            if (x1 > 0 && x1 < mapWidth - 1 && y1 > 0 && y1 < mapHeight - 1) {
                map[y1][x1] = 0;
            }
        }
    }

    function floodFill(x, y) {
        if (x < 0 || x >= mapWidth || y < 0 || y >= mapHeight || map[y][x] === 1) return;

        map[y][x] = 2; // Mark as visited

        floodFill(x + 1, y);
        floodFill(x - 1, y);
        floodFill(x, y + 1);
        floodFill(x, y - 1);
    }

    function isReachable() {
        let reachable = false;
        for (let y = 0; y < mapHeight; y++) {
            for (let x = 0; x < mapWidth; x++) {
                if (map[y][x] === 0) {
                    floodFill(x, y);
                    reachable = true;
                    break;
                }
            }
            if (reachable) break;
        }
        return reachable;
    }

    function generateMap() {
        map.forEach(row => row.fill(1)); // Reset map to all walls

        createRoom(5, 5, 50, 50);
        createRoom(60, 60, 40, 40);
        createCorridor(30, 30, 70, 70);

        if (!isReachable()) {
            generateMap(); // Regenerate if not all areas are reachable
        }

        // Add spawn points and weapon pickups
        map[5][5] = 3; // Spawn point
        map[45][45] = 4; // Weapon pickup
    }

    function drawMap() {
        for (let y = 0; y < mapHeight; y++) {
            for (let x = 0; x < mapWidth; x++) {
                switch (map[y][x]) {
                    case 0:
                        ctx.fillStyle = 'gray';
                        break;
                    case 1:
                        ctx.fillStyle = 'black';
                        break;
                    case 3:
                        ctx.fillStyle = 'green';
                        break;
                    case 4:
                        ctx.fillStyle = 'red';
                        break;
                    default:
                        ctx.fillStyle = 'white';
                }
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }

    function addMinimapLegend() {
        const legendCanvas = document.createElement('canvas');
        legendCanvas.width = 100;
        legendCanvas.height = 50;
        const legendCtx = legendCanvas.getContext('2d');

        legendCtx.fillStyle = 'black';
        legendCtx.fillRect(0, 0, 20, 20);
        legendCtx.fillStyle = 'gray';
        legendCtx.fillRect(25, 0, 20, 20);
        legendCtx.fillStyle = 'green';
        legendCtx.fillRect(50, 0, 20, 20);
        legendCtx.fillStyle = 'red';
        legendCtx.fillRect(75, 0, 20, 20);

        document.body.appendChild(legendCanvas);
    }

    function addGenerateButton() {
        const button = document.createElement('button');
        button.textContent = 'Generate New Map';
        button.addEventListener('click', () => {
            generateMap();
            drawMap();
        });
        document.body.appendChild(button);
    }

    addMinimapLegend();
    addGenerateButton();

    generateMap();
    drawMap();
}
```

Solution B: ```javascript
function generateFPSMap(canvasId) {
    const canvas = document.getElementById(canvasId);
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');
    const N = 500;
    const occupancy = new Uint8Array(N * N);
    const visited = new Uint8Array(N * N);
    const roomCount = 8;
    const maxAttempts = 20;
    const roomMinSize = 70;
    const roomMaxSize = 150;
    const spawnCount = 6;
    const weaponCount = 6;

    function randomInt(min, max) {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function placeRooms() {
        const rooms = [];
        let attempts = 0;
        while (rooms.length < roomCount && attempts < 1000) {
            const w = randomInt(roomMinSize, roomMaxSize);
            const h = randomInt(roomMinSize, roomMaxSize);
            const x = randomInt(0, N - w);
            const y = randomInt(0, N - h);
            let overlap = false;
            for (const r of rooms) {
                if (x < r.x + r.w && x + w > r.x && y < r.y + r.h && y + h > r.y) {
                    overlap = true;
                    break;
                }
            }
            if (!overlap) {
                rooms.push({x, y, w, h});
                for (let i = x; i < x + w; i++) {
                    for (let j = y; j < y + h; j++) {
                        occupancy[j * N + i] = 1;
                    }
                }
            }
            attempts++;
        }
        return rooms;
    }

    function connectRooms(rooms) {
        for (let i = 0; i < rooms.length - 1; i++) {
            const a = rooms[i];
            const b = rooms[i + 1];
            const ax = a.x + Math.floor(a.w / 2);
            const ay = a.y + Math.floor(a.h / 2);
            const bx = b.x + Math.floor(b.w / 2);
            const by = b.y + Math.floor(b.h / 2);
            if (randomInt(0, 1) === 0) {
                carveHorizontal(ax, bx, ay);
                carveVertical(ax, bx, ay, by);
            } else {
                carveVertical(ax, bx, ay, by);
                carveHorizontal(ax, bx, by);
            }
        }
    }

    function carveHorizontal(x1, x2, y) {
        const min = Math.min(x1, x2);
        const max = Math.max(x1, x2);
        for (let x = min; x <= max; x++) {
            occupancy[y * N + x] = 1;
        }
    }

    function carveVertical(x1, x2, y1, y2) {
        const min = Math.min(y1, y2);
        const max = Math.max(y1, y2);
        for (let y = min; y <= max; y++) {
            occupancy[y * N + x1] = 1;
        }
    }

    function floodFill(startX, startY) {
        visited.fill(0);
        const stack = [];
        stack.push(startX * N + startY);
        while (stack.length) {
            const idx = stack.pop();
            if (visited[idx]) continue;
            visited[idx] = 1;
            const x = idx % N;
            const y = Math.floor(idx / N);
            if (x > 0 && occupancy[idx - 1] && !visited[idx - 1]) stack.push(idx - 1);
            if (x < N - 1 && occupancy[idx + 1] && !visited[idx + 1]) stack.push(idx + 1);
            if (y > 0 && occupancy[idx - N] && !visited[idx - N]) stack.push(idx - N);
            if (y < N - 1 && occupancy[idx + N] && !visited[idx + N]) stack.push(idx + N);
        }
    }

    function allReachable(rooms) {
        floodFill(0, 0);
        for (const r of rooms) {
            for (let i = r.x; i < r.x + r.w; i++) {
                for (let j = r.y; j < r.y + r.h; j++) {
                    if (occupancy[j * N + i] && !visited[j * N + i]) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    function placeItems(count, color) {
        const items = [];
        let attempts = 0;
        while (items.length < count && attempts < 1000) {
            const x = randomInt(0, N - 1);
            const y = randomInt(0, N - 1);
            if (occupancy[y * N + x] && !visited[y * N + x]) {
                items.push({x, y});
            }
            attempts++;
        }
        return items;
    }

    function draw() {
        ctx.fillStyle = 'black';
        ctx.clearRect(0, 0, N, N);
        // draw floor
        ctx.fillStyle = 'gray';
        for (let i = 0; i < N * N; i++) {
            if (occupancy[i]) {
                const x = i % N;
                const y = Math.floor(i / N);
                ctx.fillRect(x, y, 1, 1);
            }
        }
        // spawn points
        for (const p of spawnPoints) {
            ctx.fillStyle = 'green';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        }
        // weapon pickups
        for (const p of weaponPoints) {
            ctx.fillStyle = 'red';
            ctx.beginPath();
            ctx.arc(p.x, p.y, 3, 0, 2 * Math.PI);
            ctx.fill();
        }
        // legend
        ctx.fillStyle = 'rgba(0,0,0,0.7)';
        ctx.fillRect(10, N - 80, 120, 70);
        ctx.fillStyle = 'white';
        ctx.font = '12px Arial';
        ctx.fillText('Legend', 15, N - 60);
        ctx.fillStyle = 'black';
        ctx.fillRect(15, N - 45, 10, 10);
        ctx.fillStyle = 'gray';
        ctx.fillRect(15, N - 30, 10, 10);
        ctx.fillStyle = 'green';
        ctx.fillRect(15, N - 15, 10, 10);
        ctx.fillStyle = 'red';
        ctx.fillRect(15, N, 10, 10);
        ctx.fillStyle = 'white';
        ctx.fillText('Walls', 30, N - 36);
        ctx.fillText('Floors', 30, N - 21);
        ctx.fillText('Spawn', 30, N - 6);
        ctx.fillText('Weapon', 30, N + 9);
    }

    function generate() {
        let success = false;
        for (let attempt = 0; attempt < maxAttempts && !success; attempt++) {
            occupancy.fill(0);
            const rooms = placeRooms();
            connectRooms(rooms);
            if (allReachable(rooms)) {
                spawnPoints = placeItems(spawnCount, 'green');
                weaponPoints = placeItems(weaponCount, 'red');
                success = true;
            }
        }
        draw();
    }

    let spawnPoints, weaponPoints;

    // button
    const btn = document.createElement('button');
    btn.textContent = 'Generate New Map';
    btn.style.position = 'absolute';
    btn.style.left = canvas.offsetLeft + 'px';
    btn.style.top = canvas.offsetTop + canvas.height + 10 + 'px';
    btn.style.width = '150px';
    document.body.appendChild(btn);
    btn.addEventListener('click', generate);
    generate();
}
```

